<template><el-card><template #header>Integration</template><el-form inline><el-input v-model="form.code" placeholder="Code"/><el-input v-model="form.name" placeholder="Name"/><el-input v-model="form.endpoint_url" placeholder="URL"/><el-button @click="add">Add endpoint</el-button></el-form><el-table :data="endpoints"><el-table-column prop="code" label="Code"/><el-table-column prop="name" label="Name"/><el-table-column prop="endpoint_url" label="URL"/></el-table><h3>Subscriptions</h3><el-table :data="subscriptions"><el-table-column prop="endpoint_id" label="Endpoint"/><el-table-column prop="event_type" label="Event"/></el-table></el-card></template>
<script setup>import{reactive,ref,onMounted}from'vue';import{listEndpoints,createEndpoint,listSubscriptions}from'../../api/integration';const endpoints=ref([]),subscriptions=ref([]),form=reactive({code:'',name:'',endpoint_url:'',authentication_type:'NONE'});async function load(){endpoints.value=(await listEndpoints()).data||[];subscriptions.value=(await listSubscriptions()).data||[]}async function add(){await createEndpoint(form);await load()}onMounted(load)</script>